   156→    // === 파이프라인 구성 함수 ===
   157→
   158→    // 물리 계획에 새로운 연산자 추가
   159→    func physical_plan_add_op(pp: *PhysicalPlan, op_type: i32, col_idx: i32, agg_type: i32, limit: i32) -> i32 {
   160→        if pp.op_count >= MAX_OPS {
   161→            return PHYS_ERR_FULL;
   162→        }
   163→
   164→        let op_idx = pp_alloc_op_slot(pp);
   165→        if op_idx < 0 {
   166→            return PHYS_ERR_FULL;
   167→        }
   168→
   169→        pp.ops[op_idx].op_type = op_type;
   170→        pp.ops[op_idx].col_idx = col_idx;
   171→        pp.ops[op_idx].agg_type = agg_type;
   172→        pp.ops[op_idx].limit_count = limit;
   173→        pp.ops[op_idx].is_used = true;
   174→
   175→        return op_idx;
   176→    }
   177→
   178→    // 두 연산자를 파이프라인으로 연결 (from_idx → to_idx)
   179→    func physical_plan_connect(pp: *PhysicalPlan, from_idx: i32, to_idx: i32) -> i32 {
   180→        if from_idx < 0 || from_idx >= MAX_OPS || to_idx < 0 || to_idx >= MAX_OPS {
   181→            return PHYS_ERR_INVALID_PLAN;
   182→        }
   183→
   184→        if !pp.ops[from_idx].is_used || !pp.ops[to_idx].is_used {
   185→            return PHYS_ERR_NOT_FOUND;
   186→        }
   187→
   188→        pp.ops[from_idx].next_op = to_idx;
   189→        return PHYS_OK;
   190→    }
   191→
   192→    // === 비용 추정 함수 ===
   193→
   194→    // 물리 계획의 총 비용 계산
   195→    func physical_plan_get_cost(pp: *PhysicalPlan) -> i64 {
   196→        let total_cost = 0;
   197→        let op_idx = pp.root_op_idx;
   198→        let visited = 0;
   199→
   200→        // 루트부터 시작하여 파이프라인 순회
   201→        for visited = 0; visited < MAX_OPS && op_idx >= 0 && visited < pp.op_count; visited = visited + 1 {
   202→            let op = pp.ops[op_idx];
   203→
   204→            if op.op_type == PHYS_PLAN_TABLE_SCAN {
   205→                // TABLE_SCAN: O(n)
   206→                total_cost = total_cost + 1000;
   207→            } else if op.op_type == PHYS_PLAN_INDEX_SCAN {
   208→                // INDEX_SCAN: O(log n)
   209→                total_cost = total_cost + 100;
   210→            } else if op.op_type == PHYS_PLAN_FILTER {
   211→                // FILTER: O(k) (k = 필터 조건 복잡도)
   212→                total_cost = total_cost + 50;
   213→            } else if op.op_type == PHYS_PLAN_SORT {
   214→                // SORT: O(n log n)
   215→                total_cost = total_cost + 500;
   216→            } else if op.op_type == PHYS_PLAN_LIMIT {
   217→                // LIMIT: O(1)
   218→                total_cost = total_cost + 10;
   219→            } else if op.op_type == PHYS_PLAN_AGGREGATE {
   220→                // AGGREGATE: O(n)
   221→                total_cost = total_cost + 200;
   222→            }
   223→
   224→            op_idx = op.next_op;
   225→        }
   226→
   227→        return total_cost;
   228→    }
