   258→
   259→    // 물리 계획에서 다음 사용 가능한 연산자 슬롯 할당
   260→    @inline
   261→    func pp_alloc_op_slot(pp: *PhysicalPlan) -> i32 {
   262→        if pp.op_count >= MAX_OPS {
   263→            return PHYS_ERR_FULL;
   264→        }
   265→
   266→        let op_idx = pp.op_count;
   267→        pp.op_count = pp.op_count + 1;
